CREATE TYPE public.adapter_status AS ENUM ('training','evaluating','deployed_active','archived');
CREATE TYPE public.sovereign_jurisdiction AS ENUM ('EU_GDPR_AI_Act','US_HIPAA','SG_PDPA','Air_Gapped_OnPrem');
CREATE TABLE public.ai_models (id text PRIMARY KEY, name text NOT NULL, source text NOT NULL DEFAULT 'catalog');
GRANT SELECT ON public.ai_models TO anon, authenticated;
GRANT ALL ON public.ai_models TO service_role;
ALTER TABLE public.ai_models ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public model catalog" ON public.ai_models FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.fine_tune_adapters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), base_model_id text NOT NULL REFERENCES public.ai_models(id), adapter_name text NOT NULL, rank integer NOT NULL DEFAULT 16 CHECK (rank IN (8,16,32,64)), alpha integer NOT NULL DEFAULT 32 CHECK (alpha > 0), target_modules jsonb NOT NULL DEFAULT '["q_proj","v_proj"]', training_cost_usd numeric NOT NULL DEFAULT 0, eval_pass_rate_improvement numeric NOT NULL DEFAULT 0, status public.adapter_status NOT NULL DEFAULT 'evaluating', source text NOT NULL DEFAULT 'sample-replay', report jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.fine_tune_adapters TO authenticated;
GRANT ALL ON public.fine_tune_adapters TO service_role;
ALTER TABLE public.fine_tune_adapters ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members read adapters" ON public.fine_tune_adapters FOR SELECT TO authenticated USING (public.is_org_member(org_id,auth.uid()));
CREATE POLICY "managers write adapters" ON public.fine_tune_adapters FOR ALL TO authenticated USING (public.can_manage_org(org_id,auth.uid())) WITH CHECK (public.can_manage_org(org_id,auth.uid()));
CREATE TABLE public.speculative_route_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), target_model_id text NOT NULL REFERENCES public.ai_models(id), draft_model_id text NOT NULL REFERENCES public.ai_models(id), acceptance_rate_pct numeric NOT NULL DEFAULT 0 CHECK (acceptance_rate_pct BETWEEN 0 AND 100), latency_reduction_pct numeric NOT NULL DEFAULT 0, shared_kv_cache_hits numeric NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, source text NOT NULL DEFAULT 'sample-replay', config jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.speculative_route_configs TO authenticated;
GRANT ALL ON public.speculative_route_configs TO service_role;
ALTER TABLE public.speculative_route_configs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members read routes" ON public.speculative_route_configs FOR SELECT TO authenticated USING (public.is_org_member(org_id,auth.uid()));
CREATE POLICY "managers write routes" ON public.speculative_route_configs FOR ALL TO authenticated USING (public.can_manage_org(org_id,auth.uid())) WITH CHECK (public.can_manage_org(org_id,auth.uid()));
CREATE TABLE public.sovereignty_compliance_audits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), model_id text NOT NULL REFERENCES public.ai_models(id), jurisdiction public.sovereign_jurisdiction NOT NULL, data_residency_region text NOT NULL, zero_data_retention_verified boolean NOT NULL DEFAULT false, audit_signature_hash text, last_inspected_at timestamptz, source text NOT NULL DEFAULT 'sample-scorecard', report jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sovereignty_compliance_audits TO authenticated;
GRANT ALL ON public.sovereignty_compliance_audits TO service_role;
ALTER TABLE public.sovereignty_compliance_audits ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members read audits" ON public.sovereignty_compliance_audits FOR SELECT TO authenticated USING (public.is_org_member(org_id,auth.uid()));
CREATE POLICY "managers write audits" ON public.sovereignty_compliance_audits FOR ALL TO authenticated USING (public.can_manage_org(org_id,auth.uid())) WITH CHECK (public.can_manage_org(org_id,auth.uid()));
CREATE INDEX phase6_adapter_org ON public.fine_tune_adapters(org_id,created_at DESC);
CREATE INDEX phase6_route_org ON public.speculative_route_configs(org_id,created_at DESC);
CREATE INDEX phase6_audit_org ON public.sovereignty_compliance_audits(org_id,created_at DESC);
COMMENT ON TABLE public.sovereignty_compliance_audits IS 'Sample/imported evidence records; signature validity is not legal certification.';